package com.paymentplatform.transfer_service.api;
import com.paymentplatform.transfer_service.domain.*;import com.paymentplatform.transfer_service.security.ServiceActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class MerchantController {
 private final MerchantService merchants;private final TransferWorkflow transfers;
 public MerchantController(MerchantService merchants,TransferWorkflow transfers){this.merchants=merchants;this.transfers=transfers;}
 public record Payment(@NotNull UUID merchantId,@NotNull UUID senderWalletId,@NotNull @Positive Long amount,@NotNull @Min(0) Long maxFee,@NotBlank @Pattern(regexp="[0-9]{6}") String pin){@Override public String toString(){return "MerchantPayment[REDACTED]";}}
 private String operator(Jwt jwt){String actor=jwt.getSubject();if(!"operator".equals(jwt.getClaims().get("actor_type"))||actor==null||actor.isBlank()||actor.length()>128||!actor.equals(actor.strip())||actor.chars().anyMatch(Character::isISOControl))throw new ApiException(HttpStatus.FORBIDDEN,"OPERATOR_REQUIRED","A stable signed operator is required.");return actor;}
 @PostMapping("/v1/merchants") ResponseEntity<?> create(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody MerchantService.Request request){return ResponseEntity.status(201).cacheControl(CacheControl.noStore()).body(merchants.create(jwt.getClaimAsString("integrator_id"),operator(jwt),request));}
 @GetMapping("/v1/merchants/{id}") ResponseEntity<?> get(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){ServiceActor.requireService(jwt);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(merchants.get(jwt.getClaimAsString("integrator_id"),id));}
 @PostMapping("/internal/v1/merchants/{id}/state") ResponseEntity<?> state(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@Valid @RequestBody MerchantService.StateRequest request){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(merchants.state(jwt.getClaimAsString("integrator_id"),operator(jwt),id,request));}
 @PostMapping("/v1/merchant-payments") ResponseEntity<?> pay(@AuthenticationPrincipal Jwt jwt,@RequestHeader("Idempotency-Key") @Pattern(regexp="[A-Za-z0-9][A-Za-z0-9._:-]{0,127}") String key,@Valid @RequestBody Payment request){String tenant=jwt.getClaimAsString("integrator_id"),actor=ServiceActor.requireService(jwt);UUID wallet=merchants.payableWallet(tenant,request.merchantId());var result=transfers.accept(tenant,actor,"merchant-"+RequestKeys.hash(key,"merchant-payment"),new TransferRequest(request.senderWalletId(),wallet,request.amount(),request.maxFee(),"XOF",request.pin()));var view=result.response();return ResponseEntity.status(view.status().equals("COMPLETED")?201:view.status().equals("REJECTED")?422:202).cacheControl(CacheControl.noStore()).header("Location","/v1/transfers/"+view.id()).header("Idempotency-Replayed",Boolean.toString(result.replayed())).body(view);}
}
